"""Constructor contracts and propagation of intent shape into lower()."""
from .common import *
from .ast_relations import grouped_relations,python_stages

def signature_clauses(m):
 stages=python_stages()+[
 S('step_classes',"SELECT c.*,EXISTS(SELECT 1 FROM nodes bases JOIN nodes base ON base.__path=bases.__path AND base.parent=bases.id AND base.kind!='keyword_argument' WHERE bases.__path=c.__path AND bases.parent=c.id AND bases.kind='argument_list' AND rx_matches(base.text,'IntentStep')) AS intent FROM classes c WHERE EXISTS(SELECT 1 FROM nodes bases JOIN nodes base ON base.__path=bases.__path AND base.parent=bases.id AND base.kind!='keyword_argument' WHERE bases.__path=c.__path AND bases.parent=c.id AND bases.kind='argument_list' AND rx_matches(base.text,'(?:ServerPlanStep|IntentStep)'))",('__path','id')),
 S('dataclasses',"SELECT c.*,rx_matches(w.text,'(?s)@(?:[\\w.]*\\.)?dataclass\\s*\\([^)]*\\bfrozen\\s*=\\s*True') AND rx_matches(c.name,'(?:Config|Payload)$') AS static FROM classes c JOIN nodes w ON w.__path=c.__path AND w.id=c.parent AND w.kind='decorated_definition' WHERE rx_matches(w.text,'(?m)^\\s*@(?:[\\w.]*\\.)?dataclass\\b')",('__path','name')),
 S('signature_methods',"SELECT m.*,c.intent FROM methods m JOIN step_classes c ON c.__path=m.__path AND c.id=m.cls WHERE NOT EXISTS(SELECT 1 FROM functions outer_fn WHERE outer_fn.__path=m.__path AND outer_fn.__start<m.__start AND outer_fn.__end>=m.__end) AND NOT EXISTS(SELECT 1 FROM nodes last_stmt WHERE last_stmt.__path=m.__path AND last_stmt.parent=m.body_kind||':'||m.body_start||':'||m.body_end AND last_stmt.kind='raise_statement' AND rx_matches(last_stmt.text,'^raise\\s+NotImplementedError\\s*\\(') AND NOT EXISTS(SELECT 1 FROM nodes other WHERE other.__path=m.__path AND other.parent=last_stmt.parent AND other.kind!='comment' AND (other.__start>last_stmt.__start OR other.__start<last_stmt.__start AND other.kind NOT IN ('expression_statement','delete_statement','pass_statement'))) AND NOT EXISTS(SELECT 1 FROM nodes expr WHERE expr.__path=m.__path AND expr.parent=last_stmt.parent AND expr.kind='expression_statement' AND NOT EXISTS(SELECT 1 FROM nodes v WHERE v.__path=expr.__path AND v.parent=expr.id AND v.kind IN ('assignment','string','concatenated_string','integer','float','none','true','false'))))",('__path','id')),
 S('annotations',"SELECT n.__path,n.id,n.text,n.__start,n.__end,coalesce(rx_extract(n.text,'^\\s*(?:[\\w.]+\\.)?([A-Za-z_]\\w*)',1),'') AS head,EXISTS(SELECT 1 FROM descendants d JOIN nodes a ON a.__path=d.__path AND a.id=d.node WHERE d.__path=n.__path AND d.root=n.id AND (a.kind IN ('union_type','binary_operator') AND instr(a.text,'|')>0 OR a.kind='identifier' AND a.text IN ('Union','Optional'))) AS union_type,EXISTS(SELECT 1 FROM descendants d JOIN nodes a ON a.__path=d.__path AND a.id=d.node WHERE d.__path=n.__path AND d.root=n.id AND a.kind='identifier' AND rx_matches(a.text,'ServerRef$')) AS server_ref FROM nodes n WHERE n.kind='type'",('__path','id')),
 S('annotation_contracts',"SELECT a.*,a.server_ref AND NOT a.union_type OR NOT a.union_type AND (a.head='type' AND instr(a.text,'[')>0 OR rx_matches(a.text,"+q(r'^\s*(?:[A-Za-z_]\w*\.)*(?:'+'|'.join(sorted(m.STRUCTURAL_CONSTANT_TYPE_NAMES))+r')\s*$')+") OR rx_matches(a.text,"+q(r'^\s*(?:(?:[A-Za-z_]\w*\.)*frozenset\s*\[\s*)+(?:[A-Za-z_]\w*\.)*(?:'+'|'.join(sorted(m.STRUCTURAL_CONSTANT_TYPE_NAMES))+r')\s*(?:\]\s*)+$')+")) AS basic FROM annotations a",('__path','id')),
 S('config_fields',"SELECT a.__path,c.name AS cls,t.id AS annotation FROM assignments a JOIN dataclasses c ON c.__path=a.__path JOIN nodes stmt ON stmt.__path=a.__path AND stmt.id=a.parent AND stmt.parent=c.body_kind||':'||c.body_start||':'||c.body_end LEFT JOIN annotations t ON t.__path=a.__path AND t.id=a.type_kind||':'||a.type_start||':'||a.type_end WHERE a.type_start IS NOT NULL",('__path','cls')),
 S('bad_configs',"WITH RECURSIVE bad(__path,name) AS (SELECT c.__path,c.name FROM dataclasses c WHERE NOT c.static AND (NOT EXISTS(SELECT 1 FROM config_fields f WHERE f.__path=c.__path AND f.cls=c.name) OR EXISTS(SELECT 1 FROM config_fields f LEFT JOIN annotation_contracts a ON a.__path=f.__path AND a.id=f.annotation WHERE f.__path=c.__path AND f.cls=c.name AND NOT coalesce(a.basic,0) AND NOT EXISTS(SELECT 1 FROM dataclasses other WHERE other.__path=a.__path AND other.name=a.head))) UNION SELECT c.__path,c.name FROM dataclasses c JOIN config_fields f ON f.__path=c.__path AND f.cls=c.name JOIN annotation_contracts a ON a.__path=f.__path AND a.id=f.annotation JOIN bad b ON b.__path=a.__path AND b.name=a.head WHERE NOT c.static AND NOT a.basic) SELECT * FROM bad",('__path','name')),
 S('signature_parameters',"SELECT p.*,n.__start,n.__end,n.line,m.name AS method,m.cls,m.intent,a.head,a.union_type,a.server_ref,coalesce(a.basic,0) OR EXISTS(SELECT 1 FROM dataclasses c WHERE c.__path=p.__path AND c.name=a.head AND NOT EXISTS(SELECT 1 FROM bad_configs b WHERE b.__path=c.__path AND b.name=c.name)) AS allowed,EXISTS(SELECT 1 FROM descendants d JOIN nodes atom ON atom.__path=d.__path AND atom.id=d.node WHERE d.__path=p.__path AND d.root=p.annotation AND atom.kind='identifier' AND atom.text IN ('str','int','float','bool','bytes')) AS raw_builtin FROM parameters p JOIN signature_methods m ON m.__path=p.__path AND m.id=p.fn JOIN nodes n ON n.__path=p.__path AND n.id=p.id LEFT JOIN annotation_contracts a ON a.__path=p.__path AND a.id=p.annotation",('__path','fn','name')),
 S('shape_attributes',"SELECT DISTINCT a.__path,m.cls,attr.attr AS name FROM signature_parameters p JOIN methods m ON m.__path=p.__path AND m.id=p.fn JOIN assignments a ON a.__path=p.__path AND a.fn=p.fn JOIN descendants d ON d.__path=a.__path AND d.root=a.value JOIN nodes v ON v.__path=d.__path AND v.id=d.node AND v.kind='identifier' AND v.text=p.name JOIN attributes attr ON attr.__path=a.__path AND attr.id=a.target AND attr.object_text='self' WHERE p.intent AND p.method='__init__' AND p.name NOT IN ('self','ref_id') AND NOT p.allowed",('__path','cls','name')),
 S('shape_values',"WITH RECURSIVE shape(__path,fn,node) AS (SELECT a.__path,m.id,a.id FROM methods m JOIN attributes a ON a.__path=m.__path AND a.__start>=m.__start AND a.__end<=m.__end AND a.object_text='self' JOIN shape_attributes s ON s.__path=m.__path AND s.cls=m.cls AND s.name=a.attr WHERE m.name='lower' UNION SELECT d.__path,s.fn,d.root FROM shape s JOIN descendants d ON d.__path=s.__path AND d.node=s.node UNION SELECT n.__path,s.fn,n.id FROM shape s JOIN assignments a ON a.__path=s.__path AND a.fn=s.fn AND a.value=s.node JOIN nodes n ON n.__path=a.__path AND n.kind='identifier' AND n.text=a.target_text AND n.__start>=(SELECT f.__start FROM functions f WHERE f.__path=a.__path AND f.id=a.fn) AND n.__end<=(SELECT f.__end FROM functions f WHERE f.__path=a.__path AND f.id=a.fn) WHERE a.target_kind='identifier') SELECT * FROM shape",('__path','fn','node')),
 S('shape_branches',"SELECT DISTINCT n.__path,n.line,m.id AS fn FROM methods m JOIN nodes n ON n.__path=m.__path AND n.__start>=m.__start AND n.__end<=m.__end JOIN shape_values s ON s.__path=n.__path AND s.fn=m.id AND s.node=CASE WHEN n.kind='conditional_expression' THEN (SELECT child.id FROM nodes child WHERE child.__path=n.__path AND child.parent=n.id AND child.ordinal=1) WHEN n.kind IN ('if_statement','elif_clause','while_statement') THEN n.condition_kind||':'||n.condition_start||':'||n.condition_end ELSE n.id END WHERE m.name='lower' AND n.kind IN ('if_statement','elif_clause','while_statement','conditional_expression','not_operator','boolean_operator')",('__path','fn','line')),
 ]
 rows=[]
 def add(code,table,where,identity='n.id'):
  query=f"SELECT n.__path AS path,n.__start AS start_byte,n.__end AS end_byte,{q(code)} AS issue,{identity} AS identity,'signature' AS detector FROM {table} n WHERE {where}"
  rows.append((('scan_source','scan_tree','scan_project_sources'),query,query))
 add('SPT-015','signature_parameters',"n.name NOT IN ('self','ref_id') AND n.raw_builtin AND NOT (n.name='config' AND EXISTS(SELECT 1 FROM dataclasses c WHERE c.__path=n.__path AND c.name=n.head))")
 add('SPT-016','signature_parameters',"n.intent AND n.method='__init__' AND n.name NOT IN ('self','ref_id') AND n.kind IN ('default_parameter','typed_default_parameter')")
 add('SPT-017','signature_parameters',"n.intent AND n.method='__init__' AND n.name NOT IN ('self','ref_id') AND NOT n.allowed")
 add('SPT-013','signature_parameters',"n.method='__init__' AND n.name!='self' AND n.server_ref AND n.union_type")
 add('SPT-014','signature_parameters',"n.method='__init__' AND n.name!='self' AND instr(lower(n.name),'table')>0 AND instr(lower(n.name),'alias')=0 AND EXISTS(SELECT 1 FROM descendants d JOIN nodes a ON a.__path=d.__path AND a.id=d.node WHERE d.__path=n.__path AND d.root=n.annotation AND a.kind='identifier' AND a.text='str')")
 add('SPT-018','functions',"EXISTS(SELECT 1 FROM shape_branches b WHERE b.__path=n.__path AND b.fn=n.id)")
 # A branch's line is the event identity and anchor, rather than its method.
 es,sql,full=rows[-1]
 sql="SELECT path,start_byte,end_byte,'SPT-018' AS issue,identity,'signature' AS detector FROM (SELECT b.__path AS path,n.__start AS start_byte,n.__end AS end_byte,b.fn||':'||b.line AS identity,row_number() OVER(PARTITION BY b.__path,b.fn,b.line ORDER BY n.__start,n.__end DESC) AS chosen FROM shape_branches b JOIN nodes n ON n.__path=b.__path AND n.line=b.line) WHERE chosen=1"
 rows[-1]=(es,sql,sql)
 return grouped_relations('state-signatures',stages,rows,['all'])
